INSERT INTO material_translations (material_id, locale, title, description, body) VALUES ('7d9f97b5-4dee-4fa5-9310-5c7740e9e6d3','ro','Circuitul apei în natură','Pas cu pas, prin imagini.','{"slides":[{"title":"Evaporarea","text":"Soarele încălzește apa din oceane, râuri și lacuri, care se transformă în vapori."},{"title":"Condensarea","text":"Vaporii se ridică, se răcesc și formează norii."},{"title":"Precipitațiile","text":"Apa cade înapoi pe Pământ sub formă de ploaie sau zăpadă."},{"title":"Scurgerea","text":"Apa se întoarce în râuri și oceane, iar circuitul reîncepe."}]}');
